const R=6371008.8;
const rad=n=>n*Math.PI/180;
const deg=n=>n*180/Math.PI;
export function distance(a,b){const p=rad(b[1]-a[1]),l=rad(b[0]-a[0]);const h=Math.sin(p/2)**2+Math.cos(rad(a[1]))*Math.cos(rad(b[1]))*Math.sin(l/2)**2;return 2*R*Math.asin(Math.sqrt(Math.min(1,h)));}
function numberCoordinate(s){const nums=s.match(/[-+]?\d+(?:\.\d+)?/g)?.map(Number);if(!nums||nums.length>3)throw Error('A coordinate could not be read. Use latitude, longitude on each line.');const [d,m=0,sec=0]=nums;if(m<0||m>=60||sec<0||sec>=60)throw Error('DMS minutes and seconds must be between 0 and 59.999.');const v=Math.abs(d)+m/60+sec/3600;return /[SW]/i.test(s)||d<0?-v:v;}
export function parseCoordinateLine(line){let parts=line.trim().split(/[,;\t]+/);if(parts.length!==2){const hemispheres=line.match(/[-+]?\d[^NSEW\n]*[NS]\s*[,;]?\s*[-+]?\d[^NSEW\n]*[EW]/i);if(hemispheres){parts=hemispheres[0].match(/[-+]?\d[^NSEW]*[NS]|[-+]?\d[^NSEW]*[EW]/gi);}else{const m=line.trim().match(/^([-+]?\d{1,3}\.\d+)\s+([-+]?\d{1,3}\.\d+)$/);if(m)parts=[m[1],m[2]];}}if(parts?.length!==2)throw Error('Use latitude, longitude on each line (for example 14.112480, 120.954680).');if(/[EW]/i.test(parts[0])||/[NS]/i.test(parts[1]))throw Error('Put latitude first, then longitude.');if(parts.some(s=>/[^\d\s+.,°º′’'″"NSEW−-]/i.test(s)))throw Error('Remove labels and other text from coordinate rows.');return [numberCoordinate(parts[1]),numberCoordinate(parts[0])];}
export function parseCoordinates(text){const points=text.trim().split(/\n+/).filter(s=>s.trim()).map((s,i)=>{try{return parseCoordinateLine(s);}catch(e){throw Error(`Line ${i+1}: ${e.message}`);}});if(points.length>1&&distance(points[0],points.at(-1))<.01)points.pop();return validatePolygon(points);}
export function validatePolygon(points){if(points.length<3)throw Error('At least three distinct boundary points are needed.');if(points.length>500)throw Error('Use no more than 500 boundary points.');for(const [i,p] of points.entries()){if(p.length!==2||!p.every(Number.isFinite)||Math.abs(p[0])>180||Math.abs(p[1])>85)throw Error(`Point ${i+1} is outside the supported GPS range (latitude ±85°, longitude ±180°). Easting/northing needs conversion to WGS 84.`);for(let j=0;j<i;j++)if(distance(p,points[j])<.01)throw Error(`Point ${i+1} repeats another corner.`);}if(Math.max(...points.map(p=>p[0]))-Math.min(...points.map(p=>p[0]))>180)throw Error('Lots crossing the antimeridian are not supported.');const orient=(a,b,c)=>(b[0]-a[0])*(c[1]-a[1])-(b[1]-a[1])*(c[0]-a[0]);const on=(a,b,p)=>Math.abs(orient(a,b,p))<1e-14&&p[0]>=Math.min(a[0],b[0])-1e-12&&p[0]<=Math.max(a[0],b[0])+1e-12&&p[1]>=Math.min(a[1],b[1])-1e-12&&p[1]<=Math.max(a[1],b[1])+1e-12;for(let i=0;i<points.length;i++)for(let j=i+1;j<points.length;j++){if(j===i+1||i===0&&j===points.length-1)continue;const a=points[i],b=points[(i+1)%points.length],c=points[j],d=points[(j+1)%points.length];if(orient(a,b,c)*orient(a,b,d)<0&&orient(c,d,a)*orient(c,d,b)<0||on(a,b,c)||on(a,b,d)||on(c,d,a)||on(c,d,b))throw Error('Boundary edges cross or touch. Put the corners in survey order.');}if(metrics(points).area<.1)throw Error('The boundary has no measurable area. Check the corner coordinates.');return points;}
export function destination(p,bearing,metres){const d=metres/R,b=rad(bearing),lat=rad(p[1]),lon=rad(p[0]);const phi=Math.asin(Math.sin(lat)*Math.cos(d)+Math.cos(lat)*Math.sin(d)*Math.cos(b));const lambda=lon+Math.atan2(Math.sin(b)*Math.sin(d)*Math.cos(lat),Math.cos(d)-Math.sin(lat)*Math.sin(phi));return [((deg(lambda)+540)%360)-180,deg(phi)];}
export function parseBearings(text,lat,lng){if(lat===''||lng===''||!Number.isFinite(+lat)||!Number.isFinite(+lng)||Math.abs(+lat)>85||Math.abs(+lng)>180)throw Error('Enter the known first corner as valid WGS 84 latitude and longitude.');let points=[[+lng,+lat]];const lines=text.trim().split(/\n+/).filter(s=>s.trim());if(lines.length<3)throw Error('Enter at least three boundary courses, including the return to the first corner.');for(let i=0;i<lines.length;i++){const m=lines[i].trim().match(/^([NS])\s*(\d+(?:\.\d+)?)\s*[°º]?\s*(?:(\d+(?:\.\d+)?)\s*['′’]\s*)?(?:(\d+(?:\.\d+)?)\s*["″]\s*)?([EW])\s*[,;:]?\s*(\d+(?:\.\d+)?)\s*(?:m|meters|metres)?\s*$/i);if(!m)throw Error(`Course ${i+1}: use a quadrant bearing and metres, for example N 80° 00' E 50.00.`);const angle=+m[2]+(+(m[3]||0))/60+(+(m[4]||0))/3600,metres=+m[6];if(angle>90||+(m[3]||0)>=60||+(m[4]||0)>=60||metres<=0||metres>100000)throw Error(`Course ${i+1}: check the bearing (0–90°) and distance (0–100,000 m).`);let b=m[1].toUpperCase()==='N'?(m[5].toUpperCase()==='E'?angle:360-angle):(m[5].toUpperCase()==='E'?180-angle:180+angle);points.push(destination(points.at(-1),b,metres));}const closure=distance(points[0],points.at(-1));points.pop();const result=validatePolygon(points);return {points:result,closure};}
export function metrics(points){if(!points.length)return {area:0,perimeter:0};const lat0=rad(points[0][1]),x0=points[0][0],y0=points[0][1];const xy=points.map(p=>[rad(p[0]-x0)*R*Math.cos(lat0),rad(p[1]-y0)*R]);let sum=0,perimeter=0;for(let i=0;i<points.length;i++){const j=(i+1)%points.length;sum+=xy[i][0]*xy[j][1]-xy[j][0]*xy[i][1];perimeter+=distance(points[i],points[j]);}return {area:Math.abs(sum)/2,perimeter};}
export function kml(points){const ring=[...points,points[0]].map(p=>`${p[0]},${p[1]},0`).join(' ');return `<?xml version="1.0" encoding="UTF-8"?><kml xmlns="http://www.opengis.net/kml/2.2"><Document><name>LotLens boundary</name><Style id="lot"><LineStyle><color>ff93eed5</color><width>3</width></LineStyle><PolyStyle><color>4493eed5</color></PolyStyle></Style><Placemark><name>Approximate lot boundary</name><description>WGS 84. Review against the original survey. Not a legal boundary determination.</description><styleUrl>#lot</styleUrl><Polygon><tessellate>1</tessellate><altitudeMode>clampToGround</altitudeMode><outerBoundaryIs><LinearRing><coordinates>${ring}</coordinates></LinearRing></outerBoundaryIs></Polygon></Placemark></Document></kml>`;}
